/** The catalogue stub layer: registered between `CORE_PLUGIN` and caller plugins. */
export const CATALOGUE_STUBS_PLUGIN: PluginDefinition = {
  id: "catalogue",
  version: "1.0.0",
  commands: STUBS.map(makeStub),
};
